require __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/layout.php';require_once __DIR__.'/../app/local_deals_loyalty_v1050.php';$me=current_user();if(!$me||!has_permission('settings.manage',$me)){http_response_code(403);exit('Forbidden');}$tid=sk1050_tid();$msg='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$a=$_POST['action']??'';if($a==='settings'){db()->prepare('INSERT INTO local_deal_settings_v1050(tenant_id,enabled,merchant_self_service,approval_required,loyalty_enabled,homepage_section_enabled,expiry_alerts_enabled,points_per_redemption,updated_by,updated_at) VALUES(?,?,?,?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),merchant_self_service=VALUES(merchant_self_service),approval_required=VALUES(approval_required),loyalty_enabled=VALUES(loyalty_enabled),homepage_section_enabled=VALUES(homepage_section_enabled),expiry_alerts_enabled=VALUES(expiry_alerts_enabled),points_per_redemption=VALUES(points_per_redemption),updated_by=VALUES(updated_by),updated_at=NOW()')->execute([$tid,(int)!empty($_POST['enabled']),(int)!empty($_POST['merchant_self_service']),(int)!empty($_POST['approval_required']),(int)!empty($_POST['loyalty_enabled']),(int)!empty($_POST['homepage_section_enabled']),(int)!empty($_POST['expiry_alerts_enabled']),max(0,(int)$_POST['points_per_redemption']),(int)$me['id']]);$msg='Settings saved.';}elseif(in_array($a,['approve','reject','expire'],true)){$id=(int)$_POST['deal_id'];$status=$a==='approve'?'active':($a==='reject'?'rejected':'expired');$q=db()->prepare("UPDATE local_deals_v1050 SET status=?,approved_by=?,approved_at=CASE WHEN ?='active' THEN NOW() ELSE approved_at END,updated_at=NOW() WHERE id=? AND tenant_id=?");$q->execute([$status,(int)$me['id'],$status,$id,$tid]);$msg='Deal updated.';}}}catch(Throwable $e){$msg=$e->getMessage();}$s=sk1050_settings($tid);$q=db()->prepare('SELECT d.*,b.name business_name,u.name owner_name FROM local_deals_v1050 d LEFT JOIN businesses b ON b.id=d.business_id LEFT JOIN users u ON u.id=d.owner_user_id WHERE d.tenant_id=? ORDER BY FIELD(d.status,"pending","active","draft","expired","rejected"),d.id DESC LIMIT 200');$q->execute([$tid]);$rows=$q->fetchAll()?:[];$stats=['active'=>0,'pending'=>0,'claims'=>0,'redeemed'=>0];foreach($rows as $d){if(isset($stats[$d['status']]))$stats[$d['status']]++;$stats['claims']+=(int)$d['claimed_count'];$stats['redeemed']+=(int)$d['redeemed_count'];}page_start('Deals & Loyalty Manager',true);?><link rel="stylesheet" href="/assets/admin-deals-loyalty-v1050.css?v=1050"><main class="adl1050"><header><div><span>CUSTOMER & SERVICES</span><h1>Deals, Coupons & Loyalty</h1><p>Control merchant offers, approvals, coupon claims and loyalty rewards.</p></div><div class="links"><a href="/deals-v1050.php" target="_blank">Public Deals</a><a href="/my-wallet-v1050.php" target="_blank">Customer Wallet</a></div></header><?php if($msg):?><div class="notice"><?=sk1050_h($msg)?></div><?php endif;?><section class="stats"><article><b><?=$stats['active']?></b><span>Active Deals</span></article><article><b><?=$stats['pending']?></b><span>Pending Approval</span></article><article><b><?=number_format($stats['claims'])?></b><span>Claims</span></article><article><b><?=number_format($stats['redeemed'])?></b><span>Redemptions</span></article></section><section class="panel"><h2>Module Settings</h2><form method="post" class="settings"><input type="hidden" name="_csrf" value="<?=sk1050_h(csrf_token())?>"><input type="hidden" name="action" value="settings"><?php foreach(['enabled'=>'Deals module','merchant_self_service'=>'Merchant self-service','approval_required'=>'Admin approval required','loyalty_enabled'=>'Loyalty points','homepage_section_enabled'=>'Homepage deals section','expiry_alerts_enabled'=>'Expiry alerts'] as $k=>$l):?><label><input type="checkbox" name="<?=$k?>" value="1" <?=!empty($s[$k])?'checked':''?>> <span><?=$l?></span></label><?php endforeach;?><label>Points per redemption <input type="number" name="points_per_redemption" min="0" value="<?=(int)$s['points_per_redemption']?>"></label><button>Save Settings</button></form></section><section class="panel"><h2>Merchant Offers</h2><div class="table-wrap"><table><thead><tr><th>Deal</th><th>Business / Owner</th><th>Discount</th><th>Dates</th><th>Usage</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $d):?><tr><td><b><?=sk1050_h($d['title'])?></b><small><?=sk1050_h(mb_strimwidth(strip_tags((string)$d['description']),0,80,'…'))?></small></td><td><?=sk1050_h($d['business_name']??'—')?><small><?=sk1050_h($d['owner_name']??'—')?></small></td><td><?=sk1050_h(sk1050_discount_label($d))?></td><td><?=sk1050_h(date('d M',strtotime($d['starts_at'])))?> → <?=sk1050_h(date('d M Y',strtotime($d['ends_at'])))?></td><td><?=(int)$d['claimed_count']?> / <?=(int)$d['redeemed_count']?></td><td><span class="status <?=sk1050_h($d['status'])?>"><?=sk1050_h($d['status'])?></span></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=sk1050_h(csrf_token())?>"><input type="hidden" name="deal_id" value="<?=(int)$d['id']?>"><?php if($d['status']!=='active'):?><button name="action" value="approve">Approve</button><?php endif;?><?php if($d['status']!=='rejected'):?><button class="muted" name="action" value="reject">Reject</button><?php endif;?><button class="muted" name="action" value="expire">Expire</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No deals yet.</td></tr><?php endif;?></tbody></table></div></section></main><?php require __DIR__.'/../app/end.php';?>
